constraints:
1 ≤ |str| ≤ 10^{5}

expected time complexity: O(|str|).
expected auxiliary space: O(|str|).

standard_solution_code:
class Solution:

	def check_operand(self, ch):
		return ch.isalpha() or ch.isdigit()

	def InfixtoPostfix(self, exp):
		output = ''
		stack = []
		precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
		for i in exp:
			if self.check_operand(i):
				output += i
			elif not stack:
				stack.append(i)
			elif i == '(':
				stack.append(i)
			elif i == ')':
				while stack and stack[-1] != '(':
					output += stack.pop()
				stack.pop()
			elif stack[-1] == '(' and (i == '+' or '-' or '*' or '/' or '^'):
				stack.append(i)
			elif precedence[i] > precedence[stack[-1]]:
				stack.append(i)
			else:
				while len(stack) != 0 and stack[-1] != '(' and (precedence[i] <= precedence[stack[-1]]):
					output += stack.pop()
				stack.append(i)
		while len(stack) != 0:
			output += stack.pop()
		return output
